import subprocess, json, sys

SESSION = "7718082c342d450592068e96ccb11911"
URL = "http://are-sidecar:8000/mcp"

def call_tool(tool_name, params=None):
    if params is None:
        params = {}
    payload = json.dumps({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": {
            "name": tool_name,
            "arguments": params
        }
    })
    cmd = [
        "curl", "-s", "-X", "POST", URL,
        "-H", "Content-Type: application/json",
        "-H", "Accept: application/json, text/event-stream",
        "-H", f"Mcp-Session-Id: {SESSION}",
        "-d", payload
    ]
    result = subprocess.run(cmd, capture_output=True, text=True)
    output = result.stdout.strip()
    # Parse SSE format: event: message\ndata: {...}
    for line in output.split('\n'):
        if line.startswith('data: '):
            data = json.loads(line[6:])
            return data
    return None

if __name__ == "__main__":
    tool = sys.argv[1]
    params_str = sys.argv[2] if len(sys.argv) > 2 else '{}'
    params = json.loads(params_str)
    resp = call_tool(tool, params)
    print(json.dumps(resp, indent=2))
PYEOF

